use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fs;
use std::io::Read;
use std::path::Path;

use crate::community_event::{parse_instant, valid_event_id, valid_text, MAX_EVENT_TITLE_CHARS};
use crate::game_module_package::ExecutionCompatibility;
use crate::game_target::ResolvedTarget;
use crate::plan_slots::{module_config_dir, PlanSlotFacts, PlanSlotState, EVENT_SLOT};

/// The display summaries of the occupied plan slots, regenerated by the host after each send.
pub const SLOT_OVERVIEW_FILE: &str = "slots.runplanner.json";
pub const SLOT_OVERVIEW_FORMAT: &str = "run-planner-slot-overview";
pub const SLOT_OVERVIEW_FORMAT_VERSION: u8 = 2;
pub const MAX_SLOT_SUMMARY_BYTES: usize = 4096;
const MAX_SUMMARY_TEXT_CHARS: usize = 200;
// Thirteen entries, the event slot's included, of at most one summary each, with their identities.
pub const MAX_SLOT_OVERVIEW_BYTES: usize = 65_536;

/// The planner's display summary of one plan, computed when it is sent.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct SlotSummary {
    /// Picker text, such as "Circe - Surface".
    pub label: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub plan_name: Option<String>,
    /// ISO 8601 send time.
    pub sent_at: String,
    /// Such as "Circe (Staff)".
    pub aspect: String,
    pub route: String,
    pub end_biome: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub starting_keepsake: Option<String>,
    /// The configured Fear total the Oath shows.
    pub starting_fear: u32,
    /// Such as "Thessaly · Boss"; absent for a run from the start.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub practice_start: Option<String>,
}

/// The community event the event slot's plan belongs to.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct SlotEvent {
    pub id: String,
    pub title: String,
    /// UTC ISO 8601 end time.
    pub ends_at: String,
}

impl SlotEvent {
    pub fn validate(&self) -> Result<(), String> {
        (valid_event_id(&self.id)
            && valid_text(&self.title, MAX_EVENT_TITLE_CHARS, false)
            && parse_instant(&self.ends_at).is_some())
        .then_some(())
        .ok_or_else(|| "Invalid event summary.".to_owned())
    }
}

/// One occupied slot's summary with the identity of the slot file it describes. Under
/// `flatten` the summary's `deny_unknown_fields` does not apply, so reading back is tolerant.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SlotOverviewEntry {
    #[serde(flatten)]
    pub summary: SlotSummary,
    /// Present only on the event slot's entry.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub event: Option<SlotEvent>,
    /// The plan's catalog and schema pair, so a reader marks a slot outdated without
    /// decoding it.
    pub catalog_version: String,
    pub schema_version: u32,
    pub schema_revision: u32,
    pub fingerprint: String,
}

impl SlotOverviewEntry {
    // Whether this entry describes a slot file holding exactly this plan.
    fn describes(&self, compatibility: &ExecutionCompatibility, fingerprint: &str) -> bool {
        self.catalog_version == compatibility.catalog_version
            && self.schema_version == compatibility.schema_version
            && self.schema_revision == compatibility.schema_revision
            && self.fingerprint == fingerprint
    }
}

/// The display record of the slot just written: its summary and, for the event slot, its event.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SentEntry {
    pub slot: u8,
    pub summary: SlotSummary,
    pub event: Option<SlotEvent>,
}

#[derive(Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct SlotOverview {
    pub format: String,
    pub format_version: u8,
    pub slots: BTreeMap<u8, SlotOverviewEntry>,
}

impl SlotSummary {
    /// Refuses a summary too large or with blank or overlong text before anything is written.
    pub fn validate(&self) -> Result<(), String> {
        let texts = [
            Some(&self.label),
            self.plan_name.as_ref(),
            Some(&self.sent_at),
            Some(&self.aspect),
            Some(&self.route),
            Some(&self.end_biome),
            self.starting_keepsake.as_ref(),
            self.practice_start.as_ref(),
        ];
        let valid = texts
            .into_iter()
            .flatten()
            .all(|text| !text.trim().is_empty() && text.chars().count() <= MAX_SUMMARY_TEXT_CHARS);
        let size = serde_json::to_vec(self).map_or(usize::MAX, |bytes| bytes.len());
        (valid && size <= MAX_SLOT_SUMMARY_BYTES)
            .then_some(())
            .ok_or_else(|| "Invalid plan slot summary.".to_owned())
    }
}

/// The event slot as found on disk with the event its overview entry names, which is reported
/// only while the slot's file still holds the plan the entry describes.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct EventSlotFacts {
    #[serde(flatten)]
    pub facts: PlanSlotFacts,
    pub event: Option<SlotEvent>,
}

/// Whether the overview on disk still holds an entry for `slot`, whatever its slot file holds.
pub fn has_entry(target: &ResolvedTarget, slot: u8) -> bool {
    matches!(module_config_dir(target), Ok(Some(directory))
        if read_overview(&directory.join(SLOT_OVERVIEW_FILE)).contains_key(&slot))
}

/// The summary the overview holds for a slot while it still describes the slot's plan.
pub fn slot_summary(target: &ResolvedTarget, facts: &PlanSlotFacts) -> Option<SlotSummary> {
    let (Some(compatibility), Some(fingerprint), Ok(Some(directory))) = (
        &facts.compatibility,
        &facts.plan_fingerprint,
        module_config_dir(target),
    ) else {
        return None;
    };
    read_overview(&directory.join(SLOT_OVERVIEW_FILE))
        .remove(&facts.slot)
        .filter(|entry| entry.describes(compatibility, fingerprint))
        .map(|entry| entry.summary)
}

pub fn describe_event_slot(target: &ResolvedTarget, facts: PlanSlotFacts) -> EventSlotFacts {
    let event = match (
        &facts.compatibility,
        &facts.plan_fingerprint,
        module_config_dir(target),
    ) {
        (Some(compatibility), Some(fingerprint), Ok(Some(directory))) => {
            read_overview(&directory.join(SLOT_OVERVIEW_FILE))
                .remove(&facts.slot)
                .filter(|entry| entry.describes(compatibility, fingerprint))
                .and_then(|entry| entry.event)
        }
        _ => None,
    };
    EventSlotFacts { facts, event }
}

/// Reads the previous overview; a missing, linked, oversized or invalid file holds no entries.
pub fn read_overview(path: &Path) -> BTreeMap<u8, SlotOverviewEntry> {
    let Ok(metadata) = fs::symlink_metadata(path) else {
        return BTreeMap::new();
    };
    if metadata.file_type().is_symlink()
        || !metadata.is_file()
        || metadata.len() > MAX_SLOT_OVERVIEW_BYTES as u64
    {
        return BTreeMap::new();
    }
    let mut bytes = Vec::new();
    let read = fs::File::open(path).and_then(|file| {
        file.take(MAX_SLOT_OVERVIEW_BYTES as u64 + 1)
            .read_to_end(&mut bytes)
    });
    read.ok()
        .and_then(|_| serde_json::from_slice::<SlotOverview>(&bytes).ok())
        .filter(|overview| {
            overview.format == SLOT_OVERVIEW_FORMAT
                && overview.format_version == SLOT_OVERVIEW_FORMAT_VERSION
        })
        .map(|overview| overview.slots)
        .unwrap_or_default()
}

/// The overview for the slots as they are now: a slot keeps an entry only while its file
/// still holds the plan the entry describes; `sent` replaces the entry of the slot just written.
/// A readable slot without a known summary has no entry.
pub fn regenerate(
    previous: BTreeMap<u8, SlotOverviewEntry>,
    slots: &[PlanSlotFacts],
    sent: Option<SentEntry>,
) -> SlotOverview {
    let mut previous = previous;
    let mut sent = sent;
    let entries = slots
        .iter()
        .filter_map(|facts| {
            if !matches!(facts.state, PlanSlotState::Present | PlanSlotState::Stale) {
                return None;
            }
            let compatibility = facts.compatibility.clone()?;
            let fingerprint = facts.plan_fingerprint.clone()?;
            let (summary, event) = match sent.take() {
                Some(entry) if entry.slot == facts.slot => (entry.summary, entry.event),
                other => {
                    sent = other;
                    let kept = previous
                        .remove(&facts.slot)
                        .filter(|entry| entry.describes(&compatibility, &fingerprint))?;
                    (kept.summary, kept.event)
                }
            };
            // Only the event slot's entry names an event, and only a valid one.
            let event = event.filter(|event| facts.slot == EVENT_SLOT && event.validate().is_ok());
            Some((
                facts.slot,
                SlotOverviewEntry {
                    summary,
                    event,
                    catalog_version: compatibility.catalog_version,
                    schema_version: compatibility.schema_version,
                    schema_revision: compatibility.schema_revision,
                    fingerprint,
                },
            ))
        })
        .collect();
    SlotOverview {
        format: SLOT_OVERVIEW_FORMAT.to_owned(),
        format_version: SLOT_OVERVIEW_FORMAT_VERSION,
        slots: entries,
    }
}

/// Refuses an overview larger than a reader accepts, rather than writing one it would drop.
pub fn encode_overview(overview: &SlotOverview) -> Result<String, String> {
    let encoded = serde_json::to_string(overview).expect("the slot overview always encodes");
    (encoded.len() <= MAX_SLOT_OVERVIEW_BYTES)
        .then_some(encoded)
        .ok_or_else(|| format!("slot overview exceeds the {MAX_SLOT_OVERVIEW_BYTES}-byte limit"))
}

#[cfg(test)]
pub mod test_support {
    use super::SlotSummary;

    pub fn event() -> super::SlotEvent {
        super::SlotEvent {
            id: "2026-w42-staff".to_owned(),
            title: "Week 42: Staff sprint".to_owned(),
            ends_at: "2026-10-19T00:00:00Z".to_owned(),
        }
    }

    pub fn summary(label: &str) -> SlotSummary {
        SlotSummary {
            label: label.to_owned(),
            plan_name: Some("Surface Phial run".to_owned()),
            sent_at: "2026-10-12T10:00:00.000Z".to_owned(),
            aspect: "Circe (Staff)".to_owned(),
            route: "Surface".to_owned(),
            end_biome: "Olympus".to_owned(),
            starting_keepsake: Some("Silver Wheel".to_owned()),
            starting_fear: 12,
            practice_start: None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::test_support::{event, summary};
    use super::*;
    use crate::game_target::test_support::TemporaryDirectory;

    // A plan of the test catalog and schema 96 at the given revision.
    fn compatibility(revision: u32) -> ExecutionCompatibility {
        ExecutionCompatibility {
            format: "run-planner-execution".to_owned(),
            catalog_version: "c".to_owned(),
            schema_version: 96,
            schema_revision: revision,
        }
    }

    fn facts(slot: u8, state: PlanSlotState, revision: Option<u32>, print: &str) -> PlanSlotFacts {
        PlanSlotFacts {
            slot,
            state,
            modified_at_ms: None,
            compatibility: revision.map(compatibility),
            route_key: None,
            biome_keys: Vec::new(),
            plan_fingerprint: (state != PlanSlotState::Empty).then(|| print.to_owned()),
            project_id: None,
            display_name: None,
            weapon_key: None,
            aspect_key: None,
            has_source: false,
        }
    }

    fn entry(label: &str, revision: u32, print: &str) -> SlotOverviewEntry {
        SlotOverviewEntry {
            summary: summary(label),
            event: None,
            catalog_version: "c".to_owned(),
            schema_version: 96,
            schema_revision: revision,
            fingerprint: print.to_owned(),
        }
    }

    fn sent(slot: u8, label: &str) -> Option<SentEntry> {
        Some(SentEntry {
            slot,
            summary: summary(label),
            event: None,
        })
    }

    #[test]
    fn regeneration_keeps_only_entries_that_still_describe_their_slot() {
        let previous = BTreeMap::from([
            (1, entry("kept", 0, "f1")),
            (2, entry("replaced elsewhere", 0, "old")),
            (3, entry("cleared", 0, "f3")),
            (4, entry("rebuilt", 1, "f4")),
            (5, entry("overwritten", 0, "f5")),
        ]);
        let slots = [
            facts(1, PlanSlotState::Present, Some(0), "f1"),
            facts(2, PlanSlotState::Present, Some(0), "f2"),
            facts(3, PlanSlotState::Empty, None, ""),
            facts(4, PlanSlotState::Stale, Some(0), "f4"),
            facts(5, PlanSlotState::Present, Some(0), "f5b"),
            facts(6, PlanSlotState::Stale, None, "bare"),
            facts(7, PlanSlotState::Unreadable, None, ""),
            facts(12, PlanSlotState::Present, Some(0), "f12"),
        ];
        let overview = regenerate(previous, &slots, sent(5, "sent"));
        assert_eq!(
            overview.slots,
            BTreeMap::from([(1, entry("kept", 0, "f1")), (5, entry("sent", 0, "f5b"))])
        );
        let stale = regenerate(
            BTreeMap::from([(4, entry("stale", 1, "f4"))]),
            &[facts(4, PlanSlotState::Stale, Some(1), "f4")],
            None,
        );
        assert_eq!(stale.slots.len(), 1);
    }

    #[test]
    fn the_overview_encodes_numbered_slots_and_omits_absent_fields() {
        let mut practice = summary("Circe - Surface");
        practice.plan_name = None;
        practice.starting_keepsake = None;
        practice.practice_start = Some("Thessaly · Boss".to_owned());
        let overview = regenerate(
            BTreeMap::new(),
            &[
                facts(2, PlanSlotState::Present, Some(0), "f2"),
                facts(10, PlanSlotState::Present, Some(0), "f10"),
            ],
            Some(SentEntry {
                slot: 10,
                summary: practice,
                event: None,
            }),
        );
        let encoded = encode_overview(&overview).unwrap();
        assert_eq!(
            encoded,
            r#"{"format":"run-planner-slot-overview","formatVersion":2,"slots":{"10":{"label":"Circe - Surface","sentAt":"2026-10-12T10:00:00.000Z","aspect":"Circe (Staff)","route":"Surface","endBiome":"Olympus","startingFear":12,"practiceStart":"Thessaly · Boss","catalogVersion":"c","schemaVersion":96,"schemaRevision":0,"fingerprint":"f10"}}}"#
        );
        let empty = regenerate(BTreeMap::new(), &[], None);
        assert_eq!(
            encode_overview(&empty).unwrap(),
            r#"{"format":"run-planner-slot-overview","formatVersion":2,"slots":{}}"#
        );
    }

    #[test]
    fn reading_the_previous_overview_tolerates_missing_and_invalid_files() {
        let temporary = TemporaryDirectory::new("overview-read");
        let path = temporary.0.join(SLOT_OVERVIEW_FILE);
        assert!(read_overview(&path).is_empty());
        let overview = SlotOverview {
            format: SLOT_OVERVIEW_FORMAT.to_owned(),
            format_version: SLOT_OVERVIEW_FORMAT_VERSION,
            slots: (1..=12)
                .map(|slot| (slot, entry(&"x".repeat(200), 0, &format!("f{slot}"))))
                .collect(),
        };
        let encoded = encode_overview(&overview).unwrap();
        fs::write(&path, &encoded).unwrap();
        assert_eq!(read_overview(&path).len(), 12);
        for invalid in [
            encoded.replace("formatVersion\":2", "formatVersion\":1"),
            encoded.replace("run-planner-slot-overview", "run-planner-slot"),
            encoded.replace("\"fingerprint\"", "\"print\""),
            "not json".to_owned(),
        ] {
            fs::write(&path, invalid).unwrap();
            assert!(read_overview(&path).is_empty());
        }
    }

    #[test]
    fn an_overview_larger_than_a_reader_accepts_is_refused() {
        let oversized = SlotOverview {
            format: SLOT_OVERVIEW_FORMAT.to_owned(),
            format_version: SLOT_OVERVIEW_FORMAT_VERSION,
            slots: (1..=12)
                .map(|slot| (slot, entry("label", 0, &"f".repeat(6000))))
                .collect(),
        };
        assert_eq!(
            encode_overview(&oversized),
            Err("slot overview exceeds the 65536-byte limit".to_owned())
        );
    }

    #[test]
    fn summaries_with_blank_or_overlong_text_are_refused() {
        assert_eq!(summary("Circe - Surface").validate(), Ok(()));
        let mut blank = summary(" ");
        assert!(blank.validate().is_err());
        blank.label = "x".repeat(201);
        assert!(blank.validate().is_err());
        let mut keepsake = summary("ok");
        keepsake.starting_keepsake = Some(String::new());
        assert!(keepsake.validate().is_err());
        let decoded: Result<SlotSummary, _> = serde_json::from_str(
            r#"{"label":"a","sentAt":"t","aspect":"a","route":"r","endBiome":"e","startingFear":0,"arcana":[]}"#,
        );
        assert!(decoded.is_err());
    }

    #[test]
    fn the_event_slot_entry_carries_its_event_and_keeps_it_while_its_file_holds_the_plan() {
        let written = regenerate(
            BTreeMap::new(),
            &[
                facts(0, PlanSlotState::Present, Some(0), "e"),
                facts(1, PlanSlotState::Present, Some(0), "f1"),
            ],
            Some(SentEntry {
                slot: 0,
                summary: summary("Circe - Surface"),
                event: Some(event()),
            }),
        );
        let encoded = encode_overview(&written).unwrap();
        assert!(
            encoded.contains(r#""startingFear":12,"event":{"id":"2026-w42-staff","title":"Week 42: Staff sprint","endsAt":"2026-10-19T00:00:00Z"},"catalogVersion":"c","schemaVersion":96,"schemaRevision":0,"fingerprint":"e"}"#),
            "{encoded}"
        );
        let temporary = TemporaryDirectory::new("overview-event");
        let path = temporary.0.join(SLOT_OVERVIEW_FILE);
        fs::write(&path, &encoded).unwrap();
        let previous = read_overview(&path);
        assert_eq!(previous[&0].event, Some(event()));
        let kept = regenerate(
            previous.clone(),
            &[
                facts(0, PlanSlotState::Present, Some(0), "e"),
                facts(2, PlanSlotState::Present, Some(0), "f2"),
            ],
            sent(2, "Momus - Underworld"),
        );
        assert_eq!(kept.slots[&0].event, Some(event()));
        assert_eq!(kept.slots[&2].event, None);
        let cleared = regenerate(previous, &[facts(0, PlanSlotState::Empty, None, "")], None);
        assert!(cleared.slots.is_empty());
    }

    #[test]
    fn event_summaries_are_bounded() {
        assert_eq!(event().validate(), Ok(()));
        let mut invalid = event();
        invalid.ends_at = "next week".to_owned();
        assert!(invalid.validate().is_err());
        let mut invalid = event();
        invalid.title = "x".repeat(81);
        assert!(invalid.validate().is_err());
        let mut invalid = event();
        invalid.id = "Week 42".to_owned();
        assert!(invalid.validate().is_err());
    }

    #[test]
    fn only_the_event_slot_keeps_an_event_and_only_a_valid_one() {
        let mut misplaced = entry("misplaced", 0, "f3");
        misplaced.event = Some(event());
        let mut tampered = entry("tampered", 0, "e");
        tampered.event = Some(SlotEvent {
            title: "Week\u{202E}42".to_owned(),
            ..event()
        });
        let regenerated = regenerate(
            BTreeMap::from([(3, misplaced), (0, tampered)]),
            &[
                facts(0, PlanSlotState::Present, Some(0), "e"),
                facts(3, PlanSlotState::Present, Some(0), "f3"),
                facts(4, PlanSlotState::Present, Some(0), "f4"),
            ],
            Some(SentEntry {
                slot: 4,
                summary: summary("sent"),
                event: Some(event()),
            }),
        );
        assert_eq!(regenerated.slots.len(), 3);
        assert!(regenerated
            .slots
            .values()
            .all(|entry| entry.event.is_none()));
    }
}
